// src/utils/soundEffects.ts

const SEND_SOUND_B64 =
    "data:audio/wav;base64,";

const RECEIVE_SOUND_B64 =
    "data:audio/wav;base64,";

const REACT_SOUND_B64 =
    "data:audio/wav;base64,";

const CLEAR_SOUND_B64 =
    "data:audio/wav;base64,";

let audioContext: AudioContext | null = null;
let audioUnlocked = false;

const getAudioContext = (): AudioContext | null => {
    try {
        if (audioContext) return audioContext;

        const AudioContextClass =
            window.AudioContext ||
            (window as typeof window & { webkitAudioContext?: typeof AudioContext })
                .webkitAudioContext;

        if (!AudioContextClass) return null;

        audioContext = new AudioContextClass();
        return audioContext;
    } catch {
        return null;
    }
};

export const unlockSounds = () => {
    if (audioUnlocked) return;

    const ctx = getAudioContext();
    if (!ctx) return;

    if (ctx.state === "suspended") {
        ctx.resume().catch(() => undefined);
    }

    audioUnlocked = true;
};

if (typeof window !== "undefined") {
    window.addEventListener("pointerdown", unlockSounds, {
        once: true,
        passive: true,
    });
}

const isMuted = () => {
    try {
        return localStorage.getItem("sound_muted") === "true";
    } catch {
        return false;
    }
};

const playAudio = (base64: string, volume = 0.16, playbackRate = 1) => {
    if (isMuted()) return;

    try {
        const audio = new Audio(base64);
        audio.volume = volume;
        audio.playbackRate = playbackRate;
        audio.preload = "auto";

        void audio.play().catch(() => {
            console.warn("Audio context playback deferred until a gesture interaction occurs.");
        });
    } catch (e) {
        console.warn("Audio playback failed:", e);
    }
};

export const playSendSound = () => {
    playAudio(SEND_SOUND_B64, 0.14, 1);
};

export const playReceiveSound = () => {
    playAudio(RECEIVE_SOUND_B64, 0.16, 1);
};

export const playReactSound = () => {
    playAudio(REACT_SOUND_B64, 0.13, 1);
};

export const playClearSound = () => {
    playAudio(CLEAR_SOUND_B64, 0.15, 1);
};
